using System.Text.Json;
using System.Text.RegularExpressions;

using Xunit;

/// <summary>
/// The website, held to the repository it describes.
///
/// <para>Three of these pages are generated by <c>build/Make-Pages.mjs</c> from Markdown, and that
/// generator is run BY HAND. Nothing in CI runs it, because the site has no build step - what is
/// committed under <c>website/public</c> is exactly what Netlify serves. So the failure mode this
/// class exists for is somebody editing <c>PRIVACY.md</c>, committing, and shipping a privacy page
/// that still says the old thing. A published policy that disagrees with the policy in the
/// repository is worse than having neither.</para>
///
/// <para>The tests below therefore compare the SHIPPED bytes against their sources rather than
/// reading the generator and believing it. A test that only checked the generator's source would
/// pass on the day somebody forgot to run it, which is the only day it matters.</para>
/// </summary>
public class WebsiteTests
{
    private const string Site = "https://findra-search.netlify.app";

    private static readonly string Index = Repo.Read("website/public/index.html");
    private static readonly string NotFound = Repo.Read("website/public/404.html");
    private static readonly string Llms = Repo.Read("website/public/llms.txt");
    private static readonly string Sitemap = Repo.Read("website/public/sitemap.xml");
    private static readonly string Netlify = Repo.Read("netlify.toml");

    /// <summary>Every generated page, with the Markdown it is generated from and the Markdown twin
    /// published beside it. This list is the same one <c>build/Make-Pages.mjs</c> holds; if a
    /// fourth page is added there and not here, the sitemap test below is what notices.</summary>
    public static TheoryData<string, string> Generated => new()
    {
        { "privacy", "PRIVACY.md" },
        { "about", "website/content/about.md" },
        { "contact", "website/content/contact.md" },
    };

    // ------------------------------------------------------------------ the pages say their source

    /// <summary>
    /// The published Markdown twin is the source file, byte for byte.
    ///
    /// <para>This is the strongest assertion available and it is nearly free, so it comes first.
    /// The twin exists so that an agent asking for <c>text/markdown</c>, and a person who would
    /// rather read the file, get the real policy rather than a paraphrase of it - and a copy that
    /// has drifted is a paraphrase whether or not anybody meant it to be.</para>
    /// </summary>
    [Theory]
    [MemberData(nameof(Generated))]
    public void ThePublishedMarkdownIsTheSourceFileAndNotACopyThatHasDrifted(string slug, string source)
    {
        Assert.Equal(Repo.Read(source), Repo.Read($"website/public/{slug}.md"));
    }

    /// <summary>
    /// The generated HTML page carries every sentence its Markdown does.
    ///
    /// <para>Compared as prose rather than as markup: the generator turns <c>##</c> into
    /// <c>&lt;h2&gt;</c> and rewraps hard-wrapped paragraphs, so the bytes cannot match and should
    /// not be expected to. What must match is what the page SAYS.</para>
    ///
    /// <para>The document's own H1 is excluded on both sides, because the page deliberately carries
    /// a different one - <c>PRIVACY.md</c> opens "Privacy" for somebody who came looking for the
    /// policy, and the page opens "Nothing leaves your machine, except one request" for somebody
    /// deciding whether to trust the product.</para>
    /// </summary>
    [Theory]
    [MemberData(nameof(Generated))]
    public void EverySentenceInTheMarkdownReachesThePage(string slug, string source)
    {
        string page = Unbroken(Prose(Repo.Read($"website/public/{slug}/index.html")));

        foreach (string sentence in Sentences(Repo.Read(source)))
        {
            Assert.True(
                page.Contains(sentence, StringComparison.Ordinal),
                $"website/public/{slug}/index.html does not carry this sentence from {source}, so " +
                $"the two have drifted apart - run `node build/Make-Pages.mjs`:\n  {sentence}");
        }
    }

    /// <summary>
    /// And nothing was added to the page that the Markdown does not say.
    ///
    /// <para>The opposite direction matters as much and is the easier one to get wrong: an
    /// obligation invented in HTML, or a caveat quietly dropped from the Markdown, both leave the
    /// two disagreeing. The page's own shell - navigation, footer, the heading and the two chips -
    /// is not prose from the source and is excluded by reading only the <c>&lt;article&gt;</c>.</para>
    /// </summary>
    [Theory]
    [MemberData(nameof(Generated))]
    public void ThePageSaysNothingTheMarkdownDoesNot(string slug, string source)
    {
        string markdown = Unbroken(Strip(Repo.Read(source)));

        foreach (string sentence in Sentences(Article(Repo.Read($"website/public/{slug}/index.html"))))
        {
            Assert.True(
                markdown.Contains(sentence, StringComparison.Ordinal),
                $"website/public/{slug}/index.html says something {source} does not:\n  {sentence}");
        }
    }

    // ------------------------------------------------------------------ the share card

    /// <summary>
    /// The card the social platforms crop to is really 1200 by 630, and the page says so.
    ///
    /// <para>Both halves are load-bearing. The dimensions are declared because WhatsApp will not
    /// fetch an image to measure it and shows no preview at all rather than guess; and a declared
    /// size that disagrees with the file is worse than none, because the platforms lay the card out
    /// from what was declared and then paint something a different shape into it.</para>
    ///
    /// <para>The previous <c>og:image</c> was a product screenshot at 820 by 626 - 1.31:1 against
    /// the 1.91:1 X and Facebook crop to - which is the defect this asserts against.</para>
    /// </summary>
    [Fact]
    public void TheShareCardIsTheSizeThePageDeclaresAndTheSizeThePlatformsCropTo()
    {
        (int width, int height) = PngSize("website/public/share/card.png");
        Assert.Equal(1200, width);
        Assert.Equal(630, height);

        Assert.Contains($@"<meta property=""og:image"" content=""{Site}/share/card.png"">", Index, StringComparison.Ordinal);
        Assert.Contains(@"<meta property=""og:image:width"" content=""1200"">", Index, StringComparison.Ordinal);
        Assert.Contains(@"<meta property=""og:image:height"" content=""630"">", Index, StringComparison.Ordinal);

        // An image with no alt text is an image an agent, and anybody using a screen reader on a
        // shared link, is told nothing about.
        Assert.Matches(@"<meta property=""og:image:alt"" content=""[^""]{20,}"">", Index);

        // The square exists only to be posted by hand: Instagram reads no Open Graph at all. It
        // is still held to its size, because a feed crops anything that is not square.
        (int side, int tall) = PngSize("website/public/share/square.png");
        Assert.Equal(1080, side);
        Assert.Equal(1080, tall);
    }

    /// <summary>Every page declares the whole Open Graph set, not the half that happens to be
    /// enough for one platform. A page missing <c>og:site_name</c> or <c>og:locale</c> is a page an
    /// entity resolver has to guess at.</summary>
    [Theory]
    [InlineData("website/public/index.html")]
    [InlineData("website/public/privacy/index.html")]
    [InlineData("website/public/about/index.html")]
    [InlineData("website/public/contact/index.html")]
    public void EveryPageCarriesTheWholeOpenGraphSet(string path)
    {
        string html = Repo.Read(path);
        foreach (string property in new[]
                 { "og:type", "og:site_name", "og:locale", "og:url", "og:title", "og:description",
                   "og:image", "og:image:width", "og:image:height", "og:image:alt" })
        {
            Assert.Contains($@"property=""{property}""", html, StringComparison.Ordinal);
        }

        Assert.Contains(@"name=""twitter:card"" content=""summary_large_image""", html, StringComparison.Ordinal);
        Assert.Contains(@"<link rel=""canonical""", html, StringComparison.Ordinal);
        Assert.Contains(@"<html lang=""en"">", html, StringComparison.Ordinal);
    }

    // ------------------------------------------------------------------ structured data

    /// <summary>
    /// The homepage's JSON-LD parses, and every fact in it is a fact stated elsewhere.
    ///
    /// <para>Structured data is the one part of a page nobody proofreads, because nobody sees it.
    /// A version number left behind at 0.1.0 after a release, or a price that says the product
    /// costs money, is wrong in the machine-readable copy while the human-readable one beside it is
    /// right.</para>
    /// </summary>
    [Fact]
    public void TheStructuredDataParsesAndAgreesWithTheRepository()
    {
        Match block = Regex.Match(
            Index, @"<script type=""application/ld\+json"">(?<json>.*?)</script>", RegexOptions.Singleline);
        Assert.True(block.Success, "the homepage carries no JSON-LD");

        using JsonDocument document = JsonDocument.Parse(block.Groups["json"].Value);
        JsonElement graph = document.RootElement.GetProperty("@graph");

        JsonElement app = graph.EnumerateArray().Single(n => n.GetProperty("@type").GetString() == "SoftwareApplication");
        Assert.Equal("Findra", app.GetProperty("name").GetString());
        Assert.Equal($"{Site}/", app.GetProperty("url").GetString());

        // The version lives in Directory.Build.props and nowhere else. This is a second place it
        // is written down, so this is the test that keeps it from becoming a second source.
        string version = Regex.Match(Repo.Read("Directory.Build.props"), @"<Version>([^<]+)</Version>").Groups[1].Value;
        Assert.Equal(version, app.GetProperty("softwareVersion").GetString());

        // Free means free, and a price of anything else here is a claim the whole site contradicts.
        Assert.Equal("0", app.GetProperty("offers").GetProperty("price").GetString());
        Assert.True(app.GetProperty("isAccessibleForFree").GetBoolean());
        Assert.Contains("Windows", app.GetProperty("operatingSystem").GetString()!, StringComparison.Ordinal);

        // The person named here is the person the About page names, and the handle beside it is
        // the one the licence, the NOTICE and the repository URL all use. Both are needed: an
        // entity resolver matching "Liraz Amir" to this project has only the alternateName to go
        // on, and one matching "blakazulu" has only the name.
        JsonElement person = graph.EnumerateArray().Single(n => n.GetProperty("@type").GetString() == "Person");
        Assert.Equal("Liraz Amir", person.GetProperty("name").GetString());
        Assert.Equal("blakazulu", person.GetProperty("alternateName").GetString());
        Assert.Contains("Liraz Amir", Repo.Read("website/content/about.md"), StringComparison.Ordinal);
        Assert.True(person.TryGetProperty("contactPoint", out _), "no contactPoint, which is the point of the Person node");
    }

    /// <summary>
    /// No page invents a postal address or a telephone number.
    ///
    /// <para>This is a refusal rather than an omission, and it is written down as a test because it
    /// looks like a gap. Readiness checks score an Organization node higher when it carries a
    /// <c>PostalAddress</c> and a <c>telephone</c>, and the obvious way to make one pass is to put
    /// something in those fields. Findra is one person and an open repository; a switchboard nobody
    /// answers, or a home address, would be the only dishonest thing on the site.</para>
    /// </summary>
    [Fact]
    public void NothingOnTheSiteInventsAPostalAddressOrATelephoneNumber()
    {
        foreach (string path in new[]
                 { "website/public/index.html", "website/public/contact/index.html",
                   "website/public/about/index.html", "website/public/privacy/index.html",
                   "website/public/llms.txt" })
        {
            // Comments only. The structured data is deliberately NOT stripped: an address added
            // to the JSON-LD is exactly the thing this test exists to catch, and a check that read
            // only the visible text could not see it.
            string text = WithoutComments(Repo.Read(path));
            Assert.DoesNotContain("PostalAddress", text, StringComparison.Ordinal);
            Assert.DoesNotContain("streetAddress", text, StringComparison.Ordinal);
            Assert.DoesNotContain("\"telephone\"", text, StringComparison.Ordinal);
        }

        // And the contact page says so out loud, rather than leaving a reader to wonder whether
        // the details were merely forgotten.
        string contact = Flat(Repo.Read("website/content/contact.md"));
        Assert.Contains("no phone number and no postal address", contact, StringComparison.OrdinalIgnoreCase);
    }

    // ------------------------------------------------------------------ finding your way

    /// <summary>
    /// The sitemap lists every page the site has, and every page it lists exists.
    ///
    /// <para>Both directions. A sitemap missing a page is a page nothing will index; a sitemap
    /// naming a page that is not there is a 404 handed to a crawler on the site's own authority.
    /// </para>
    /// </summary>
    [Fact]
    public void TheSitemapAndThePagesOnDiskAreTheSameSet()
    {
        HashSet<string> listed = Regex.Matches(Sitemap, @"<loc>([^<]+)</loc>")
            .Select(m => m.Groups[1].Value)
            .ToHashSet(StringComparer.Ordinal);

        HashSet<string> onDisk = new(StringComparer.Ordinal) { $"{Site}/" };
        foreach (string slug in new[] { "privacy", "about", "contact" })
        {
            Assert.True(Repo.Exists($"website/public/{slug}/index.html"), $"/{slug}/ is missing");
            onDisk.Add($"{Site}/{slug}/");
        }

        Assert.Equal(onDisk.OrderBy(u => u, StringComparer.Ordinal),
                     listed.OrderBy(u => u, StringComparer.Ordinal));

        // 404.html is deliberately absent from the sitemap and says so with a robots meta.
        Assert.Contains(@"<meta name=""robots"" content=""noindex"">", NotFound, StringComparison.Ordinal);
    }

    /// <summary>
    /// The 404 page is a map rather than an apology.
    ///
    /// <para>Netlify serves this file, with a real 404 status, for any path that does not exist.
    /// Before it existed the platform's own default page was served - which carries a
    /// <c>netlify.new</c> referral link in its body, on a site whose whole argument is that nothing
    /// is reaching out anywhere. The reader here is a person who mistyped or an agent that guessed
    /// a URL, and both need the list of real ones.</para>
    /// </summary>
    [Fact]
    public void TheNotFoundPageNamesEveryPlaceAReaderCouldGoInstead()
    {
        foreach (string href in new[]
                 { "\"/\"", "\"/about/\"", "\"/contact/\"", "\"/privacy/\"",
                   "\"/llms.txt\"", "\"/sitemap.xml\"", "\"/robots.txt\"" })
        {
            Assert.Contains($"href={href}", NotFound, StringComparison.Ordinal);
        }

        // Nothing WE author advertises the platform the site happens to be hosted on. That is the
        // whole of what this can promise, and the limit is worth stating: Netlify injects a
        // hosting-provider meta tag and a netlify.new referral comment into every HTML response on
        // the current plan, after these bytes leave the repository. The live page is not clean and
        // no test here can make it so - a plan or a platform setting can. What this catches is the
        // thing that IS in our hands: a referral link somebody pastes into a file.
        //
        // Comments are excluded because two of them explain this very situation.
        Assert.DoesNotContain("netlify.new", WithoutComments(NotFound), StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("netlify.new", WithoutComments(Index), StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// The homepage's footer links to the site's own pages rather than to files on GitHub.
    ///
    /// <para>The privacy policy used to be reachable only as a Markdown file in the repository,
    /// which is a fine place for it to live and a poor place to send somebody who is deciding
    /// whether to install the product.</para>
    /// </summary>
    [Fact]
    public void TheFooterSendsAReaderToThePagesAndNotToRawFiles()
    {
        Assert.Contains(@"<a href=""/privacy/"">Privacy</a>", Index, StringComparison.Ordinal);
        Assert.Contains(@"<a href=""/about/"">About</a>", Index, StringComparison.Ordinal);
        Assert.Contains(@"<a href=""/contact/"">Contact</a>", Index, StringComparison.Ordinal);
        Assert.DoesNotContain("blob/main/PRIVACY.md", Index, StringComparison.Ordinal);
    }

    // ------------------------------------------------------------------ what agents are told

    /// <summary>
    /// <c>llms.txt</c> says when to reach for Findra and when not to, and does not claim to be
    /// something Findra is not.
    ///
    /// <para>The "when not to" half is the half worth testing. Findra is a desktop application
    /// with no API, no accounts and no server, hosted as static files on a platform that publishes
    /// its own MCP server, CLI and SDKs - and a readiness scan of this domain credited every one of
    /// those to Findra. Saying plainly that there is nothing to call is what stops that.</para>
    /// </summary>
    [Fact]
    public void TheAgentInstructionsSayWhenToUseFindraAndWhatItIsNot()
    {
        Assert.Contains("## When to use this", Llms, StringComparison.Ordinal);
        Assert.Contains("Do not reach for Findra when", Llms, StringComparison.Ordinal);

        string flat = Flat(Llms);
        Assert.Contains("no API", flat, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("no MCP server", flat, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("Netlify's own MCP server, CLI and SDKs are the host's, not Findra's",
                        flat, StringComparison.Ordinal);

        // Every page, and every Markdown twin, is named - otherwise this file is a summary rather
        // than an index, and an agent still has to guess at URLs.
        foreach (string url in new[]
                 { $"{Site}/", $"{Site}/about/", $"{Site}/contact/", $"{Site}/privacy/",
                   $"{Site}/index.md", $"{Site}/about.md", $"{Site}/contact.md", $"{Site}/privacy.md" })
        {
            Assert.Contains(url, Llms, StringComparison.Ordinal);
        }
    }

    /// <summary>
    /// The Markdown negotiation is wired end to end: the edge function offers exactly the pages
    /// that have a twin, and the twins are served with <c>Vary: Accept</c>.
    ///
    /// <para><c>Vary</c> is the part that looks like a detail and is not. Without it a CDN caches
    /// whichever variant it saw first and serves that to everybody after - so a browser gets
    /// Markdown, or an agent gets HTML, depending on which one knocked first.</para>
    /// </summary>
    [Fact]
    public void MarkdownNegotiationCoversEveryPageThatHasAMarkdownTwin()
    {
        string edge = Repo.Read("netlify/edge-functions/markdown.ts");

        foreach ((string path, string twin) in new[]
                 { ("/", "/index.md"), ("/about/", "/about.md"),
                   ("/contact/", "/contact.md"), ("/privacy/", "/privacy.md") })
        {
            Assert.Contains($"'{path}': '{twin}'", edge, StringComparison.Ordinal);
            Assert.True(Repo.Exists($"website/public{twin}"), $"{twin} is declared but not published");
            // Declared in `config.path` too, or the function is never invoked for that URL at all.
            Assert.Contains($"'{path}'", edge.Split("export const config")[1], StringComparison.Ordinal);
        }

        Assert.Contains("Vary = \"Accept, Accept-Encoding\"", Netlify, StringComparison.Ordinal);
        Assert.Contains("Content-Type = \"text/markdown; charset=utf-8\"", Netlify, StringComparison.Ordinal);

        // A browser sends `*/*;q=0.8`, which matches text/markdown. A negotiator that does not
        // weigh the q values hands Markdown to every human visitor.
        Assert.Contains("q=", edge, StringComparison.Ordinal);
        Assert.Contains("markdown > html", edge, StringComparison.Ordinal);
    }

    /// <summary>
    /// Nothing lives in the edge functions directory except edge functions.
    ///
    /// <para>Netlify deploys every top-level file in <c>netlify/edge-functions/</c> AS an edge
    /// function - .js, .ts, .jsx, .tsx and .mjs alike - and an edge function with no default export
    /// fails the build. This is written down as a test because of what that failure looks like from
    /// outside: the deploy does not half-work and the site does not break. It simply never happens,
    /// and the previous commit goes on being served, so everything looks fine until somebody
    /// notices that a change pushed some time ago is not live.</para>
    ///
    /// <para>That is exactly what a test file placed next to the function it tests did here. Helper
    /// files can live in a SUBDIRECTORY of that folder, which Netlify does not deploy; the node
    /// test lives in <c>tests/edge/</c> with the rest of the tests.</para>
    /// </summary>
    [Fact]
    public void TheEdgeFunctionsDirectoryHoldsNothingButEdgeFunctions()
    {
        string[] deployed = Directory.GetFiles(Repo.Path_("netlify/edge-functions"))
            .Where(f => new[] { ".js", ".ts", ".jsx", ".tsx", ".mjs" }
                .Contains(Path.GetExtension(f), StringComparer.OrdinalIgnoreCase))
            .ToArray();

        Assert.NotEmpty(deployed);

        foreach (string file in deployed)
        {
            string source = File.ReadAllText(file);
            Assert.True(
                source.Contains("export default", StringComparison.Ordinal),
                $"netlify/edge-functions/{Path.GetFileName(file)} has no default export, so Netlify " +
                "will fail the whole deploy trying to bundle it as an edge function - and a deploy " +
                "that never happens leaves the previous commit live with nothing to show it went " +
                "wrong. Only real edge functions belong in that directory.");

            // A file Netlify runs on Deno cannot use node's globals. `process.exit` in one is the
            // same mistake in a different disguise.
            Assert.DoesNotContain("process.exit", source, StringComparison.Ordinal);
        }
    }

    /// <summary>The site makes no comparative claim against a named competitor - the same rule the
    /// README and the winget listing are held to, applied to three new pages of prose.</summary>
    [Fact]
    public void TheNewPagesNameNoCompetitor()
    {
        foreach (string path in new[]
                 { "website/content/about.md", "website/content/contact.md",
                   "website/content/home.md", "website/public/llms.txt", "website/public/404.html" })
        {
            string text = Repo.Read(path);
            foreach (string name in Repo.Competitors)
            {
                Assert.DoesNotContain(name, text, StringComparison.OrdinalIgnoreCase);
            }
        }
    }

    // ------------------------------------------------------------------ reading the files

    /// <summary>A PNG's declared size, from the IHDR chunk, which is always the first one.</summary>
    private static (int Width, int Height) PngSize(string relative)
    {
        byte[] bytes = File.ReadAllBytes(Repo.Path_(relative));
        Assert.True(bytes.Length > 24, $"{relative} is too short to be a PNG");
        return (System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(16, 4)),
                System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(20, 4)));
    }

    /// <summary>The body of a generated page: what is inside its one <c>&lt;article&gt;</c>, which
    /// is the part that came from the Markdown, without the shell around it.</summary>
    private static string Article(string html)
    {
        Match m = Regex.Match(html, @"<article class=""doc"">(?<body>.*?)</article>", RegexOptions.Singleline);
        Assert.True(m.Success, "the page has no <article class=\"doc\">, so it was not generated by Make-Pages.mjs");
        return Tags(m.Groups["body"].Value);
    }

    /// <summary>A whole page as readable text.</summary>
    private static string Prose(string html) => Tags(html);

    /// <summary>HTML comments removed, and nothing else. Used by the two tests that assert a
    /// string is ABSENT: a comment saying why the page carries no postal address is not the page
    /// carrying one, and neither is a comment recording what this file replaced. Everything else,
    /// the structured data included, stays - because that is where such a thing would appear.
    /// </summary>
    private static string WithoutComments(string html) =>
        Regex.Replace(html, "<!--.*?-->", " ", RegexOptions.Singleline);

    /// <summary>The marker a block boundary leaves on both sides, so the sentence splitter treats
    /// the end of a heading the way it treats a full stop. A pilcrow, because no page here has
    /// one.</summary>
    private const char Break = '\u00b6';

    /// <summary>
    /// Whitespace flattened, and the space an inline tag leaves in front of punctuation removed.
    ///
    /// <para><c>indexed&lt;/strong&gt;, not merely</c> becomes "indexed , not merely" the moment
    /// the tag is replaced by a space, while the Markdown it came from says "indexed, not merely".
    /// Every emphasised phrase and every code span with a comma after it hits this, which is most
    /// of them.</para>
    /// </summary>
    private static string Tidy(string text) => Regex.Replace(Flat(text), @"\s+([,.;:!?])", "$1");

    /// <summary>Markup removed and entities put back, so that what remains is what a reader sees.
    /// Script and style blocks go with their contents rather than leaving their source behind as
    /// prose.</summary>
    private static string Tags(string html)
    {
        string text = Regex.Replace(html, @"<(script|style)\b.*?</\1>", " ", RegexOptions.Singleline);
        text = Regex.Replace(text, "<!--.*?-->", " ", RegexOptions.Singleline);
        // A block ends a sentence even with no full stop of its own - a heading, a bullet, a
        // table cell. Without this the heading above a paragraph and the paragraph itself flatten
        // into one run of words, and the "sentence" that comes out exists on neither side.
        text = Regex.Replace(text, @"</(h[1-6]|p|li|ul|ol|td|th|tr|pre|div|article|section)>",
                             " " + Break + " ", RegexOptions.IgnoreCase);
        text = Regex.Replace(text, "<[^>]+>", " ");
        return Tidy(text.Replace("&middot;", "·", StringComparison.Ordinal)
                        .Replace("&amp;", "&", StringComparison.Ordinal)
                        .Replace("&lt;", "<", StringComparison.Ordinal)
                        .Replace("&gt;", ">", StringComparison.Ordinal)
                        .Replace("&quot;", "\"", StringComparison.Ordinal)
                        .Replace("&copy;", "©", StringComparison.Ordinal));
    }

    /// <summary>Markdown reduced to its prose. Headings, bullets, code fences, table pipes and
    /// emphasis are markup rather than words, and the page renders them as structure.</summary>
    private static string Strip(string markdown)
    {
        // Headings, bullets and blank lines are the Markdown's own block boundaries, and they
        // become the same marker the closing tags leave on the HTML side.
        //
        // Every rule anchored to the start of a line runs BEFORE blank lines are collapsed, and
        // the order is the whole of it: collapsing "\n\n" first destroys the line start in front
        // of the FIRST bullet of every list, so that one bullet keeps its "- " while the rest lose
        // theirs - which fails on one sentence per list and looks like a content problem.
        string text = Regex.Replace(markdown, @"(?m)^```.*$", " " + Break + " ");
        text = Regex.Replace(text, @"(?m)^#{1,6}\s+(.*)$", " " + Break + " $1 " + Break + " ");
        text = Regex.Replace(text, @"(?m)^[-*]\s+", " " + Break + " ");
        text = Regex.Replace(text, @"(?m)^\|[\s|:-]+\|\s*$", " ");   // a table's rule row
        text = Regex.Replace(text, @"\n[ \t]*\n", " " + Break + " ");
        // A link is its text. The page renders `[a](mailto:a)` as "a", so leaving the target in
        // would make the two sides differ on every link that is not a bare URL.
        text = Regex.Replace(text, @"\[([^\]]+)\]\([^)]+\)", "$1");
        return Tidy(text.Replace("|", " " + Break + " ", StringComparison.Ordinal)
                        .Replace("**", "", StringComparison.Ordinal)
                        .Replace("`", "", StringComparison.Ordinal));
    }

    /// <summary>Every run of whitespace flattened to one space. Both sides are hard wrapped at
    /// columns nobody chose deliberately, and an assertion that depends on where a wrap fell breaks
    /// on the next copy-edit while the sentence it guards is still there and still correct.</summary>
    private static string Flat(string text) => Regex.Replace(text, @"\s+", " ").Trim();

    /// <summary>The block markers taken back out, for the two haystacks - a whole page, and a whole
    /// Markdown file - that are searched for a sentence rather than split into sentences.</summary>
    private static string Unbroken(string text) =>
        Flat(text.Replace(Break, ' '));

    /// <summary>
    /// The sentences worth comparing, which are the long ones.
    ///
    /// <para>A promise lives in a full sentence. Fragments - a heading, a table cell, a two-word
    /// bullet - are structure, they differ legitimately between the two renderings, and comparing
    /// them turns this into a test about formatting. Forty characters is comfortably past every
    /// heading on these three pages and comfortably under every claim on them.</para>
    /// </summary>
    private static IEnumerable<string> Sentences(string text)
    {
        // The H1 is excluded on both sides: the page carries a different one, deliberately.
        string body = Regex.Replace(text, @"(?m)\A\s*#\s+.*$", " ");

        return Regex.Split(Strip(body), @"(?<=[.!?])\s+|\s*" + Break + @"\s*")
            .Select(s => s.Trim())
            .Where(s => s.Length >= 40 && !s.Contains("http", StringComparison.Ordinal));
    }
}
